window.URINARY_CASES=[{"id":1,"name":"Rim","group":"Componentes fundamentais","marker":"1","location":"Órgão par retroperitoneal, entre aproximadamente T12 e L3, nos lados da coluna; o hilo volta-se medialmente.","bloom":"Aplicar/Analisar","dialogue":["No ambulatório, uma jovem apresenta edema, hipertensão e alteração importante da filtração sanguínea.","O problema envolve um órgão que produz urina e regula água, eletrólitos e pressão arterial.","Seu hilo fica na margem medial e ele está atrás do peritônio."],"question":"Uma colega diz que o edema e a hipertensão surgiram apenas porque a bexiga ficou cheia. Qual argumento anatômico-funcional melhor desmonta essa hipótese?","options":["O edema seria explicado principalmente por retenção na bexiga, sem repercussão sobre a filtração renal.","Uma dificuldade isolada de saída uretral explicaria obrigatoriamente a hipertensão e a alteração importante da filtração.","Uma alteração renal pode comprometer a filtração e o controle de água e sais, favorecendo os dois achados."],"challenge":"Proponha uma segunda pista clínica que ajudaria a separar alteração renal de dificuldade isolada de esvaziamento vesical.","correct":2,"explanation":"O rim participa da filtração e do equilíbrio hidroeletrolítico; a simples distensão vesical não explica, por si só, o conjunto descrito."},{"id":2,"name":"Ureter","group":"Componentes fundamentais","marker":"2","location":"Tubo muscular retroperitoneal da junção pieloureteral até a parede posterolateral da bexiga; percorre abdome e pelve.","bloom":"Aplicar/Analisar","dialogue":["Ren sente uma dor súbita no flanco que desce para a virilha; a tomografia mostra um cálculo num tubo estreito.","Esse tubo conduz urina por contrações peristálticas, mesmo sem depender da gravidade.","Ele começa na pelve renal e termina na bexiga!"],"question":"Ren pergunta: “Se eu ficar de cabeça para baixo, o cálculo sairá porque a urina mudará de direção?” Qual é a resposta mais coerente?","options":["Não: o ureter impulsiona urina por peristaltismo, e um cálculo pode continuar obstruindo o trajeto.","Ao ficar invertido, a ação da gravidade superaria necessariamente a obstrução provocada pelo cálculo.","O peristaltismo ureteral só funciona quando o corpo está em posição vertical."],"challenge":"Imagine um trajeto ureteral em três segmentos e explique onde uma obstrução mudaria a drenagem.","correct":0,"explanation":"O transporte ureteral não depende exclusivamente da gravidade; a obstrução física pode persistir apesar de mudanças posturais."},{"id":3,"name":"Bexiga urinária","group":"Componentes fundamentais","marker":"3","location":"Órgão muscular oco da pelve menor, imediatamente posterior à sínfise púbica; distende-se superiormente quando cheia.","bloom":"Analisar","dialogue":["Depois de uma lesão neurológica, uma pessoa perde a capacidade de esvaziar adequadamente o reservatório de urina.","A estrutura é um reservatório muscular, e sua contração depende do músculo detrusor.","Quando se enche, pode ultrapassar a margem superior da sínfise púbica."],"question":"Após lesão neurológica, a urina continua sendo produzida, mas o paciente não consegue esvaziar o reservatório. Qual consequência anatômica imediata é mais plausível?","options":["A pelve renal passaria a funcionar como o reservatório fisiológico até a micção.","Distensão da bexiga por retenção de urina.","O volume vesical permaneceria inalterado apesar da retenção de urina."],"challenge":"Crie uma frase que diferencie armazenamento, produção e eliminação da urina.","correct":1,"explanation":"A bexiga pode acumular urina quando seu esvaziamento está comprometido; a produção renal e a micção são processos distintos."},{"id":4,"name":"Uretra","group":"Componentes fundamentais","marker":"4","location":"Canal que se inicia no óstio interno da bexiga e termina no óstio externo; o trajeto difere entre os sexos.","bloom":"Analisar","dialogue":["Um paciente desenvolveu dificuldade para eliminar urina após lesão de um canal de saída.","A região suspeita não leva urina do rim à bexiga, e sim da bexiga ao exterior.","Existe diferença marcante entre o trajeto feminino e masculino."],"question":"A imagem mostra rins e ureteres pérvios, e a bexiga enche normalmente. Mesmo assim, há dificuldade de eliminar urina após lesão do canal de saída. Qual hipótese anatômica é mais consistente?","options":["Lesão cortical renal que, por si só, interromperia apenas a fase final da micção.","Lesão do segmento que liga a bexiga ao meio externo.","Obstrução na saída da pelve renal, mesmo com o fluxo ureteral livre na imagem."],"challenge":"Monte o percurso da urina e indique em que etapa surge o problema.","correct":1,"explanation":"A uretra é a passagem final da bexiga para o exterior, enquanto os ureteres conduzem urina até a bexiga."},{"id":5,"name":"Rim direito","group":"Posição dos rins e vasos renais","marker":"5","location":"Retroperitoneal, no lado direito da coluna, geralmente mais baixo que o esquerdo devido à presença do fígado.","bloom":"Avaliar","dialogue":["Uma imagem do abdome surpreende um aluno: o rim do lado do fígado está discretamente mais inferior.","Isso é habitualmente uma relação topográfica normal, e não um rim deslocado.","O fígado ocupa grande volume no quadrante superior direito."],"question":"Em um exame, o rim direito aparece discretamente mais baixo. Um estudante propõe registrar “deslocamento patológico”. Qual avaliação é a mais prudente?","options":["A posição mais alta do rim esquerdo é, isoladamente, prova de uma lesão renal.","A assimetria demonstra necessariamente deslocamento patológico do rim direito.","A assimetria pode ser habitual pela relação do rim direito com o fígado; é preciso analisar o restante do exame."],"challenge":"Desenhe as relações topográficas que justificam a assimetria.","correct":2,"explanation":"O rim direito costuma estar um pouco mais inferior devido ao volume do fígado; a posição isolada não determina doença."},{"id":6,"name":"Rim esquerdo","group":"Posição dos rins e vasos renais","marker":"6","location":"Retroperitoneal no lado esquerdo, geralmente mais alto; a 11ª e 12ª costelas relacionam-se à sua face posterior.","bloom":"Aplicar/Analisar","dialogue":["Após trauma na região das últimas costelas esquerdas, a equipe procura lesão de um órgão posterior.","Duas costelas podem projetar-se atrás desse órgão no lado esquerdo.","Ele costuma estar um pouco acima do correspondente direito."],"question":"Após trauma nas 11ª e 12ª costelas esquerdas, não há ferida na parte anterior do abdome. Por que a equipe ainda deve investigar o sistema urinário?","options":["Porque o rim esquerdo se relaciona posteriormente com essas costelas.","A proteção costal exclui lesão renal posterior, restando avaliar apenas os órgãos intraperitoneais.","O trauma atingiria preferencialmente o rim direito, pois ele é o único relacionado às últimas costelas esquerdas."],"challenge":"Explique por que uma lesão na parede posterior pode alcançar uma estrutura retroperitoneal.","correct":0,"explanation":"O rim esquerdo é retroperitoneal e apresenta relação posterior com a 11ª e a 12ª costelas."},{"id":7,"name":"Artéria renal direita","group":"Posição dos rins e vasos renais","marker":"7","location":"Ramo da aorta abdominal que segue à direita, em geral passando posteriormente à veia cava inferior, rumo ao hilo renal.","bloom":"Analisar","dialogue":["Na cirurgia vascular, a equipe procura um vaso arterial que parece desaparecer atrás da veia cava inferior.","É uma artéria que sai da aorta e costuma ter trajeto mais longo para alcançar o rim.","O trajeto posterior à cava é a pista decisiva."],"question":"Durante a cirurgia, um vaso sai da aorta e desaparece atrás da veia cava inferior. Se esse vaso for lesionado, qual território terá sua perfusão arterial mais diretamente ameaçada?","options":["O rim esquerdo, porque sua artéria é a que normalmente passa por trás da cava inferior.","Os dois rins igualmente, pois o vaso visualizado ainda seria a aorta antes de emitir ramos.","O rim direito, pelo trajeto habitual de sua artéria renal."],"challenge":"Faça um esquema com a aorta, a cava e o trajeto das duas artérias renais.","correct":2,"explanation":"A artéria renal direita nasce da aorta, segue para o rim direito e geralmente cruza posteriormente à veia cava inferior."},{"id":8,"name":"Artéria renal esquerda","group":"Posição dos rins e vasos renais","marker":"8","location":"Ramo lateral da aorta abdominal que segue ao hilo do rim esquerdo, usualmente mais curto que o ramo direito.","bloom":"Aplicar/Analisar","dialogue":["Um paciente jovem com hipertensão secundária apresenta estreitamento de uma artéria que se dirige diretamente ao rim esquerdo.","Essa artéria sai da aorta abdominal e costuma ser mais curta do que a do lado oposto.","O estreitamento pode comprometer a perfusão do rim e contribuir para hipertensão."],"question":"Um paciente com estreitamento da artéria que parte diretamente da aorta em direção ao rim esquerdo desenvolve hipertensão. Que ligação entre estrutura e sintoma faz mais sentido?","options":["A redução da drenagem venosa esquerda é a consequência direta do estreitamento arterial descrito.","O estreitamento reduz a perfusão renal e pode contribuir para a elevação da pressão arterial.","O estreitamento arterial bloquearia mecanicamente a pelve renal, impedindo a drenagem de urina."],"challenge":"Diferencie, em duas setas, transporte de sangue arterial e drenagem urinária.","correct":1,"explanation":"A estenose da artéria renal pode reduzir a perfusão renal e contribuir para hipertensão secundária."},{"id":9,"name":"Aorta abdominal","group":"Posição dos rins e vasos renais","marker":"Indicador","location":"Vaso arterial principal retroperitoneal, anterior aos corpos vertebrais e levemente à esquerda da linha média; origina as artérias renais.","bloom":"Analisar","dialogue":["Numa angiografia, o professor aponta o grande vaso de onde surgem as duas artérias renais.","A estrutura é arterial e continua inferiormente até sua bifurcação em artérias ilíacas comuns.","Ela não retorna sangue ao coração: distribui sangue para os órgãos."],"question":"Em uma angiografia, dois vasos chegam aos rins a partir de um grande tronco anterior à coluna. O que ocorreria primeiro com o suprimento renal se o fluxo nesse tronco fosse gravemente reduzido acima das origens renais?","options":["A principal consequência inicial seria interromper o retorno venoso pela cava, sem reduzir a perfusão arterial.","Somente o rim esquerdo perderia suprimento, pois o direito não recebe artéria originada da aorta.","A chegada de sangue arterial a ambos os rins poderia diminuir."],"challenge":"Justifique por que aorta e veia cava não são intercambiáveis no diagrama circulatório.","correct":2,"explanation":"A aorta abdominal origina as artérias renais, portanto sua redução de fluxo proximal pode afetar o suprimento arterial dos dois rins."},{"id":10,"name":"Veia renal direita","group":"Posição dos rins e vasos renais","marker":"9","location":"Vaso venoso curto que sai do hilo do rim direito e desemboca na veia cava inferior, à direita da aorta.","bloom":"Avaliar","dialogue":["Durante um transplante, a cirurgiã comenta que um dos rins oferece uma veia renal mais curta para a anastomose.","A cava inferior está do lado direito; essa proximidade encurta o trajeto venoso.","O vaso conduz sangue do rim de volta à circulação sistêmica."],"question":"Na preparação de um transplante, a equipe nota que um dos enxertos apresenta veia renal naturalmente mais curta. Qual consideração topográfica explica melhor o achado?","options":["O rim direito está próximo da veia cava inferior, encurtando o caminho de sua veia.","A veia esquerda costuma ser mais curta porque desemboca na cava pelo mesmo lado do rim.","A simetria dos rins exige comprimento aproximadamente igual das duas veias renais."],"challenge":"Indique que aspecto do comprimento venoso merece atenção ao planejar uma anastomose.","correct":0,"explanation":"A veia renal direita tende a ser mais curta pela proximidade entre o rim e a veia cava inferior."},{"id":11,"name":"Veia renal esquerda","group":"Posição dos rins e vasos renais","marker":"10","location":"Cruza anteriormente à aorta e posteriormente à artéria mesentérica superior antes de desembocar na cava inferior.","bloom":"Analisar","dialogue":["Um adolescente apresenta hematúria e dor no flanco; a imagem sugere compressão de uma veia entre dois vasos arteriais.","A artéria mesentérica superior e a aorta formam a chamada pinça vascular.","Essa veia também recebe com frequência drenagem gonadal e suprarrenal esquerdas."],"question":"Uma “pinça” entre a aorta e a artéria mesentérica superior coincide com hematúria. Qual explicação integra a imagem e o sintoma?","options":["O ureter esquerdo é pinçado entre esses vasos, causando primariamente retenção urinária.","A artéria renal esquerda é comprimida entre a aorta e a artéria mesentérica superior.","A compressão da veia renal esquerda pode prejudicar sua drenagem e associar-se à hematúria."],"challenge":"Explique por que a posição relativa dos vasos é decisiva, e não apenas seus nomes.","correct":2,"explanation":"A veia renal esquerda passa entre a aorta e a artéria mesentérica superior, onde pode sofrer compressão na síndrome do quebra-nozes."},{"id":12,"name":"Veia cava inferior","group":"Posição dos rins e vasos renais","marker":"Indicador","location":"Grande vaso venoso retroperitoneal, principalmente à direita da aorta, que recebe ambas as veias renais.","bloom":"Analisar","dialogue":["Uma imagem com contraste mostra o sangue de ambos os rins chegando a um grande vaso vertical à direita da aorta.","Esse vaso transporta sangue venoso na direção do átrio direito.","É a principal referência para entender a drenagem venosa renal."],"question":"Se um trombo dificultasse o fluxo na veia cava inferior acima da entrada das veias renais, qual circuito estaria mais diretamente prejudicado?","options":["O retorno venoso proveniente de ambos os rins em direção ao coração.","Somente a drenagem do rim esquerdo seria comprometida, pois a veia direita não chega à cava.","A alteração se restringiria à veia gonadal, sem efeito no fluxo venoso dos rins."],"challenge":"Esboce o percurso do sangue saindo de cada rim até o coração.","correct":0,"explanation":"Ambas as veias renais drenam para a cava inferior, que conduz o sangue venoso em direção ao átrio direito."},{"id":13,"name":"Artérias segmentares","group":"Posição dos rins e vasos renais","marker":"11","location":"Ramos da artéria renal que entram no seio e distribuem sangue a territórios segmentares do parênquima.","bloom":"Avaliar","dialogue":["Antes de retirar um pequeno tumor localizado, o cirurgião estuda ramos arteriais que irrigam territórios quase independentes.","Esses ramos são predominantemente terminais, com pouca circulação colateral entre segmentos.","Identificá-los ajuda a planejar a preservação de tecido renal."],"question":"Um cirurgião quer remover uma lesão pequena preservando ao máximo o restante do rim. Qual mapa anatômico mais ajuda a definir territórios de irrigação relativamente independentes?","options":["Um mapa dos ramos venosos, assumindo que eles delimitam os mesmos territórios arteriais terminais.","Um mapa dos cálices menores, assumindo correspondência exata e obrigatória com cada território arterial.","A distribuição das artérias segmentares renais."],"challenge":"Proponha como representaria em cores os segmentos vasculares de um rim em um atlas.","correct":2,"explanation":"As artérias segmentares irrigam territórios renais definidos, informação útil em cirurgias com preservação de parênquima."},{"id":14,"name":"Fáscia renal","group":"Rim — configuração externa","marker":"12","location":"Camadas fasciais que envolvem a gordura perirrenal e ajudam a fixar o rim no retroperitônio.","bloom":"Analisar","dialogue":["Um exame mostra coleção inflamatória retida ao redor do rim, com disseminação condicionada por planos fasciais.","Os planos de tecido conjuntivo delimitam o espaço perirrenal e influenciam a propagação da coleção.","Não estamos falando da membrana colada à superfície do rim."],"question":"Uma coleção infecciosa aparece ao redor do rim, mas sua disseminação acompanha limites de tecido conjuntivo. Qual interpretação é a mais adequada?","options":["Planos da fáscia renal ajudam a delimitar o espaço perirrenal e influenciam a disseminação.","A cápsula fibrosa sozinha define os limites externos de todo o compartimento perirrenal.","A gordura perirrenal atua como uma barreira rígida que impede completamente qualquer disseminação."],"challenge":"Diferencie em um desenho cápsula fibrosa, gordura perirrenal e fáscia.","correct":0,"explanation":"A fáscia renal delimita o compartimento perirrenal; seus planos podem condicionar os caminhos de uma coleção."},{"id":15,"name":"Cápsula adiposa","group":"Rim — configuração externa","marker":"13","location":"Gordura perirrenal situada ao redor da cápsula fibrosa, no interior da fáscia renal.","bloom":"Analisar","dialogue":["Num exame de imagem, aparece uma camada de gordura envolvendo diretamente o rim antes da fáscia.","Ela auxilia no amortecimento e na sustentação do órgão.","O termo gordura perirrenal descreve bem essa camada."],"question":"O exame mostra uma camada amortecedora de gordura entre a cápsula aderida ao rim e os planos fasciais. Qual conclusão sobre ela é mais precisa?","options":["A gordura pararrenal, que estaria localizada entre a cápsula fibrosa e a fáscia renal.","Trata-se da gordura perirrenal, com função protetora e de sustentação.","A cápsula fibrosa, que seria a camada de gordura diretamente aderida ao parênquima."],"challenge":"Proponha uma legenda de três camadas, da mais interna para a mais externa.","correct":1,"explanation":"A cápsula adiposa corresponde à gordura perirrenal, externa à cápsula fibrosa e interna à fáscia renal."},{"id":16,"name":"Cápsula fibrosa","group":"Rim — configuração externa","marker":"14","location":"Película conjuntiva fina intimamente aderida à superfície do parênquima renal, interna à gordura perirrenal.","bloom":"Aplicar/Analisar","dialogue":["Durante uma cirurgia, o professor mostra uma membrana delgada que reveste diretamente o tecido renal.","Ao contrário da fáscia, ela acompanha de perto a superfície do órgão.","Distensão do rim durante processos agudos pode contribuir para dor pela tensão de seus revestimentos."],"question":"Um rim aumenta rapidamente de volume em processo agudo e o paciente sente dor. Qual revestimento pode ser tensionado por estar em contato íntimo com o parênquima?","options":["A cápsula fibrosa renal.","A fáscia renal, porque é a camada que está diretamente aderida à superfície do córtex.","A gordura perirrenal, porque é a membrana íntima que reveste cada pirâmide renal."],"challenge":"Compare o papel da cápsula fibrosa e o da gordura perirrenal na proteção do órgão.","correct":0,"explanation":"A cápsula fibrosa está intimamente aderida ao rim, e sua distensão pode contribuir para dor em certos processos."},{"id":17,"name":"Polo superior","group":"Rim — configuração externa","marker":"15","location":"Extremidade cranial do rim, próxima da glândula suprarrenal e do diafragma.","bloom":"Avaliar","dialogue":["Um pequeno tumor está situado na extremidade renal imediatamente abaixo da suprarrenal.","A relação topográfica com a glândula endócrina deve ser considerada na cirurgia.","É a extremidade voltada à região diafragmática."],"question":"Uma massa é descrita como “superior e vizinha à suprarrenal”. Qual cuidado na leitura da imagem evita subestimar uma relação cirúrgica importante?","options":["Presumir que a suprarrenal só se relaciona com a margem lateral, não com os polos.","Considerar o polo inferior como a extremidade mais próxima da glândula suprarrenal.","Considerar a proximidade do polo superior do rim com a glândula suprarrenal."],"challenge":"Descreva duas estruturas que usaria como referência para orientar o polo superior.","correct":2,"explanation":"O polo superior renal é cranial e mantém relação com a glândula suprarrenal."},{"id":18,"name":"Polo inferior","group":"Rim — configuração externa","marker":"16","location":"Extremidade caudal do rim, geralmente mais lateral que o polo superior.","bloom":"Aplicar/Analisar","dialogue":["Uma pequena massa aparece na porção mais inferior de um rim, distante da suprarrenal.","Precisamos indicar ao cirurgião se a lesão está na extremidade cranial ou caudal.","Na peça, é a extremidade mais baixa e tipicamente um pouco mais lateral."],"question":"Uma lesão está na extremidade renal mais baixa e mais afastada da suprarrenal. Para informar a equipe sem confundir direções, qual descrição é a melhor?","options":["Lesão do hilo renal, pois a extremidade caudal sempre corresponde à entrada do pedículo.","Lesão do polo inferior, na extremidade caudal do rim.","Lesão no polo superior, que seria a extremidade mais afastada da glândula suprarrenal."],"challenge":"Crie um esquema de orientação cranial, caudal, medial e lateral para o rim.","correct":1,"explanation":"A descrição de localização deve usar o polo inferior, extremidade caudal geralmente um pouco mais lateral."},{"id":19,"name":"Face anterior","group":"Rim — configuração externa","marker":"17","location":"Superfície renal voltada às vísceras abdominais; as relações variam entre rim direito e esquerdo.","bloom":"Analisar","dialogue":["Numa tomografia, uma lesão renal encosta em vísceras como cólon e duodeno ou pâncreas, dependendo do lado.","São relações com órgãos situados à frente do rim.","A face oposta está relacionada à parede muscular posterior."],"question":"Uma lesão renal toca o duodeno no lado direito; outra toca o pâncreas no lado esquerdo. O que essas duas observações sugerem sobre a superfície envolvida?","options":["Ambas envolvem relações viscerais da face anterior, que variam entre rim direito e esquerdo.","A margem medial, porque todas as relações viscerais ficam concentradas dentro do hilo.","A face posterior, pois o contato com vísceras varia obrigatoriamente nessa região."],"challenge":"Construa um par de mini mapas com relações viscerais anteriores direita e esquerda.","correct":0,"explanation":"A face anterior dos rins se relaciona com vísceras diferentes conforme o lado."},{"id":20,"name":"Face posterior","group":"Rim — configuração externa","marker":"18","location":"Superfície dirigida ao diafragma e à parede posterior do abdome, próxima de psoas maior e quadrado do lombo.","bloom":"Analisar","dialogue":["Após trauma lombar, a equipe avalia uma superfície renal vizinha a músculos da parede posterior.","Psoas maior e quadrado do lombo são pistas importantes.","Também há relação com diafragma e costelas inferiores."],"question":"Uma pancada na região lombar profunda é acompanhada de lesão ao lado do psoas maior e do quadrado do lombo. Qual orientação da superfície renal se ajusta a essas pistas?","options":["A margem medial, já que ambos os músculos passam pelo hilo renal.","A face anterior, pela relação habitual com psoas e quadrado do lombo.","Posterior, por sua relação com a musculatura da parede abdominal posterior."],"challenge":"Explique como distinguir relações anteriores e posteriores em um corte axial.","correct":2,"explanation":"A face posterior do rim relaciona-se com diafragma e músculos posteriores, inclusive psoas maior e quadrado do lombo."},{"id":21,"name":"Margem lateral","group":"Rim — configuração externa","marker":"19","location":"Borda convexa do rim voltada para a parede lateral do abdome, oposta ao hilo.","bloom":"Avaliar","dialogue":["Um desenho anatômico mostra um rim com duas bordas: uma convexa, sem entrada de vasos, e outra côncava.","A entrada e saída do pedículo renal ficam na borda oposta.","A borda convexa olha lateralmente."],"question":"Ao observar um rim em peça anatômica, um colega chama a borda convexa de “hilo”. Qual correção demonstra leitura espacial adequada?","options":["A borda convexa é lateral; o hilo fica na margem medial côncava.","A convexidade corresponde à face anterior, enquanto o hilo ocupa exclusivamente a face posterior.","A borda convexa é medial e nela se encontra a abertura do hilo."],"challenge":"Projete um corte simples com marcação da margem convexa e do local de entrada do pedículo.","correct":0,"explanation":"A margem lateral do rim é convexa, enquanto o hilo se localiza medialmente."},{"id":22,"name":"Margem medial","group":"Rim — configuração externa","marker":"20","location":"Borda côncava do rim voltada para o plano mediano, onde se localiza o hilo renal.","bloom":"Analisar","dialogue":["O cirurgião localiza a borda renal pela qual entram artérias e saem veias.","É a borda côncava dirigida medialmente.","Nela se encontra a abertura para o seio renal."],"question":"Em um planejamento cirúrgico, a lesão está na borda côncava voltada para a linha média. Qual estrutura merece atenção especial nessa vizinhança?","options":["O pedículo renal que atravessa o hilo.","Os cálices menores, porque se abrem externamente em toda a extensão da margem medial.","A cápsula adiposa, porque o pedículo atravessa apenas a margem lateral oposta."],"challenge":"Justifique por que uma lesão de margem medial exige avaliação diferente de uma lesão lateral.","correct":0,"explanation":"A margem medial contém o hilo renal, via de entrada e saída de componentes do pedículo."},{"id":23,"name":"Hilo renal","group":"Rim — configuração externa","marker":"Indicador","location":"Fenda na margem medial do rim, continuidade de acesso ao seio; padrão anteroposterior frequente: veia, artéria, pelve.","bloom":"Avaliar","dialogue":["Durante uma simulação cirúrgica, três elementos se alinham da frente para trás na entrada do rim.","O padrão clássico é veia, artéria e pelve renal, embora existam variações.","É a porta de comunicação da superfície medial com o seio renal."],"question":"Um aprendiz memoriza que no hilo renal sempre estarão veia, artéria e pelve nessa ordem, sem exceções. Qual é a melhor conduta diante de uma variação observada na simulação?","options":["Classificar a disposição real como impossível, pois não existem variações do padrão anteroposterior.","Usar a ordem clássica como referência, mas verificar a disposição real dos elementos.","Identificar todos os elementos apenas pela ordem memorizada, sem conferir seus trajetos."],"challenge":"Crie uma regra de observação segura para o estudante antes de nomear estruturas do hilo.","correct":1,"explanation":"A sequência anteroposterior veia–artéria–pelve é um padrão frequente, não uma regra absoluta; variações precisam ser reconhecidas."},{"id":24,"name":"Seio renal","group":"Rim — configuração externa","marker":"21","location":"Cavidade interna do rim acessível pelo hilo, contendo vasos, gordura, cálices e pelve renal.","bloom":"Analisar","dialogue":["Uma tomografia revela um cisto próximo às estruturas coletoras, dentro de uma cavidade cheia de gordura.","A cavidade não corresponde ao tecido funcional cortical ou medular.","Por ela passam pelve, cálices, vasos e nervos."],"question":"A tomografia mostra um cisto em uma região interna rica em gordura, junto aos cálices, mas não dentro do tecido cortical. Qual consequência topográfica é mais plausível?","options":["Uma lesão do seio renal pode ficar próxima das vias coletoras e de vasos.","Uma lesão restrita ao córtex, porque a gordura do seio faz parte da camada cortical periférica.","Uma lesão necessariamente externa ao rim, porque toda gordura renal fica além da fáscia."],"challenge":"Desenhe a diferença entre a abertura do hilo e a cavidade do seio renal.","correct":0,"explanation":"O seio renal é a cavidade interna que abriga gordura, cálices, pelve, vasos e nervos."},{"id":25,"name":"Córtex renal","group":"Rim — córtex e medula","marker":"22","location":"Camada externa do parênquima logo abaixo da cápsula fibrosa, prolongando-se entre as pirâmides.","bloom":"Analisar","dialogue":["Uma doença vascular compromete preferencialmente a região periférica onde estão os corpúsculos renais.","A maior parte dos glomérulos localiza-se nessa região.","Ela está logo sob a cápsula fibrosa."],"question":"Uma doença compromete a periferia do parênquima, onde se concentram os corpúsculos renais. Qual função pode ser especialmente afetada?","options":["A filtração do sangue nos glomérulos.","A capacidade de concentração urinária por dano direto e exclusivo a estruturas da medula.","A capacidade de distensão vesical, pois corpúsculos renais controlam diretamente o detrusor."],"challenge":"Localize córtex, medula e corpúsculos renais em um desenho próprio.","correct":0,"explanation":"O córtex renal abriga os corpúsculos renais e participa diretamente da filtração glomerular."},{"id":26,"name":"Colunas renais","group":"Rim — córtex e medula","marker":"A","location":"Prolongamentos do córtex entre as pirâmides da medula, também chamados colunas de Bertin.","bloom":"Avaliar","dialogue":["Um exame mostra uma faixa de tecido cortical que se projeta entre duas pirâmides e simula uma massa.","Às vezes uma coluna de Bertin proeminente parece um pseudotumor.","O tecido mantém continuidade com o córtex e aspecto semelhante."],"question":"Uma imagem mostra uma faixa renal que parece tumor, mas mantém textura e continuidade com o córtex entre duas pirâmides. Qual hipótese deve ser considerada antes de classificá-la como massa verdadeira?","options":["Uma papila renal, porque normalmente forma uma faixa larga entre duas pirâmides.","Uma pirâmide medular com textura cortical normal, sem continuidade com o córtex.","Uma coluna renal proeminente, variante anatômica que pode simular pseudotumor."],"challenge":"Formule uma pista de imagem que favoreça a interpretação de variante anatômica.","correct":2,"explanation":"Uma coluna de Bertin é prolongamento do córtex entre pirâmides e pode simular massa benigna em imagem."},{"id":27,"name":"Medula renal","group":"Rim — córtex e medula","marker":"23","location":"Região interna do parênquima, organizada em pirâmides dirigidas para as papilas.","bloom":"Analisar","dialogue":["Uma condição com hipóxia na região profunda do rim prejudica estruturas associadas à concentração da urina.","Essa região possui ambiente osmótico importante e contém alças de Henle e ductos coletores.","Ela fica mais interna do que o córtex."],"question":"Depois de um episódio de hipóxia, um paciente perde eficiência na concentração da urina. Qual região interna merece atenção por conter alças e ductos envolvidos nesse processo?","options":["A medula renal e suas pirâmides.","O seio renal, já que sua gordura é a responsável direta pelo gradiente de concentração.","O córtex renal, pois apenas nele se encontram alças de Henle e ductos coletores."],"challenge":"Relacione em um fluxograma simples medula, ductos coletores e concentração urinária.","correct":0,"explanation":"A medula contém segmentos de alças de Henle e ductos coletores essenciais para o mecanismo de concentração urinária."},{"id":28,"name":"Pirâmides renais","group":"Rim — córtex e medula","marker":"B","location":"Estruturas cônicas da medula; bases voltadas para o córtex e ápices formando as papilas.","bloom":"Aplicar/Analisar","dialogue":["Ao cortar um rim no laboratório, a turma observa unidades triangulares com estrias convergentes.","A base de cada unidade aponta para o córtex; o ápice desemboca em direção ao cálice menor.","São formações características da medula renal."],"question":"Ao seguir o fluxo de uma gota de urina no interior de uma pirâmide, para qual região ela tende a avançar ao sair pelos ductos no ápice?","options":["Diretamente à pelve renal, sem passar pela papila e por cálices menores.","À papila renal, em direção ao cálice menor.","À cápsula fibrosa, onde os ductos coletores normalmente se abrem."],"challenge":"Represente base, ápice e direção do fluxo urinário em uma pirâmide.","correct":1,"explanation":"Os ductos convergem para a papila, ápice da pirâmide, que se projeta no cálice renal menor."},{"id":29,"name":"Papila renal","group":"Rim — córtex e medula","marker":"Indicador","location":"Ápice de uma pirâmide projetado no cálice menor, onde se abrem ductos papilares.","bloom":"Analisar","dialogue":["Uma paciente com doença predisponente à necrose papilar apresenta hematúria e fragmentos de tecido na urina.","A lesão ocorre no ápice de uma pirâmide que drena para o cálice menor.","Os ductos papilares se abrem nessa saliência."],"question":"Uma necrose compromete o ápice de uma pirâmide e fragmentos desprendidos alcançam o sistema coletor. Qual ligação anatômica explica o achado?","options":["Uma coluna renal, pois suas extremidades se projetam em cálices menores.","A base da pirâmide junto ao córtex, pois os ductos se abrem ali diretamente nos cálices.","A papila renal se projeta em um cálice menor e recebe aberturas dos ductos papilares."],"challenge":"Reconstitua em setas o trajeto inicial de um fragmento que sai da papila.","correct":2,"explanation":"A papila é o ápice da pirâmide e comunica os ductos papilares com o cálice menor."},{"id":30,"name":"Cálices renais menores","group":"Cálices e pelve renal","marker":"1","location":"Pequenas cavidades em forma de taça que abraçam papilas renais e recebem urina diretamente delas.","bloom":"Analisar","dialogue":["Um cálculo muito pequeno aparece alojado na primeira cavidade que coleta urina após sua saída pela papila.","A estrutura acolhe o ápice da pirâmide como uma taça.","Vários desses receptáculos convergem para canais coletores maiores."],"question":"Um cálculo está exatamente na primeira cavidade que recebe a urina após ela emergir da papila. Se essa cavidade ficar bloqueada, qual estrutura tem seu escoamento direto prejudicado?","options":["A papila renal correspondente, que drena para o cálice menor.","O cálice maior, porque ele recebe urina da papila antes de qualquer cálice menor.","A pelve renal, porque recebe diretamente a urina de todas as papilas, sem ramificações intermediárias."],"challenge":"Faça uma sequência de três estruturas desde a papila até um cálice maior.","correct":0,"explanation":"Os cálices menores recebem diretamente a urina das papilas; um bloqueio local pode dificultar o escoamento daquela unidade de drenagem."},{"id":31,"name":"Cálices renais maiores","group":"Cálices e pelve renal","marker":"2","location":"Ramos coletores formados pela união de cálices menores, que convergem para a pelve renal.","bloom":"Analisar","dialogue":["No exame contrastado, duas pequenas taças convergem para um coletor mais volumoso antes da pelve.","Essa formação pode ser superior, média ou inferior, com muita variação anatômica.","Ela ainda está dentro do sistema coletor intrarrenal."],"question":"Dois cálices menores desembocam em um coletor maior. Se o coletor intermediário obstruir, que raciocínio sobre a drenagem é mais coerente?","options":["A urina contornaria o cálice maior por um canal coletor alternativo obrigatório.","A obstrução afetaria necessariamente um único cálice menor, mesmo quando vários convergem ao maior.","A drenagem dos cálices menores tributários pode ser prejudicada antes de chegar à pelve renal."],"challenge":"Desenhe uma árvore de confluência com dois cálices menores e um maior.","correct":2,"explanation":"Os cálices maiores recebem urina de grupos de cálices menores e a conduzem à pelve renal."},{"id":32,"name":"Pelve renal","group":"Cálices e pelve renal","marker":"3","location":"Estrutura coletora afunilada, situada em parte no seio renal, que recebe cálices maiores e continua no ureter.","bloom":"Analisar","dialogue":["Uma ultrassonografia mostra dilatação da cavidade central coletora do rim, antes do início do ureter.","É uma área em forma de funil que recebe urina dos cálices maiores.","Um obstáculo em sua saída pode causar dilatação do sistema coletor."],"question":"A ultrassonografia mostra dilatação da região coletora central, antes do ureter. Qual explicação causal se ajusta melhor à configuração em funil?","options":["A região em funil estaria dilatada apenas por produzir mais urina, mesmo com drenagem livre.","Um obstáculo na saída da pelve renal pode represar urina no sistema coletor a montante.","A dilatação provaria uma lesão exclusivamente vascular, sem relação com a saída da urina."],"challenge":"Modele o que ocorre com o fluxo quando o funil coletor encontra uma obstrução.","correct":1,"explanation":"A pelve renal reúne urina dos cálices maiores e se continua com o ureter; obstrução na saída pode gerar dilatação a montante."},{"id":33,"name":"Parte abdominal","group":"Ureter — porções e constrições","marker":"4","location":"Trecho retroperitoneal que desce da pelve renal até a entrada da pelve, sobre a face anterior do psoas maior.","bloom":"Aplicar/Analisar","dialogue":["Na cirurgia abdominal, um vaso gonadal cruza anteriormente a um tubo que desce sobre o psoas.","É um canal muscular retroperitoneal do sistema urinário.","Ainda não ultrapassou a borda superior da pelve."],"question":"Durante uma cirurgia abdominal, a equipe vê vasos gonadais cruzando à frente de um tubo sobre o psoas maior. Que atitude anatômica é mais sensata?","options":["Seria a parte intramural, porque esse trecho terminal percorre a face do psoas maior.","Reconhecer a possibilidade de ser o ureter abdominal e conferir seu trajeto retroperitoneal.","Seria obrigatoriamente ureter pélvico, pois qualquer cruzamento de vaso gonadal ocorre junto ao útero."],"challenge":"Esquematize a relação entre psoas, ureter e vasos gonadais.","correct":1,"explanation":"A porção abdominal do ureter desce sobre o psoas maior e pode ser cruzada anteriormente por vasos gonadais."},{"id":34,"name":"Parte ilíaca","group":"Ureter — porções e constrições","marker":"5","location":"Trecho de transição sobre os vasos ilíacos, junto à borda superior da pelve.","bloom":"Analisar","dialogue":["Um cálculo para exatamente no ponto em que o trajeto urinário cruza os vasos ilíacos.","Esse cruzamento é referência topográfica e estreitamento clássico.","Fica entre o trajeto abdominal e o pélvico."],"question":"Um cálculo fica retido exatamente na transição do abdome para a pelve, sobre vasos ilíacos. Qual combinação de localização e interpretação está correta?","options":["Parte intramural do ureter, porque a entrada da pelve coincide com a parede da bexiga.","Parte abdominal do ureter, já que o cruzamento ilíaco ocorre próximo ao hilo renal.","Porção ilíaca do ureter; região de cruzamento dos vasos e estreitamento clássico."],"challenge":"Crie um marco de referência que permita encontrar essa transição em uma imagem.","correct":2,"explanation":"A chamada parte ilíaca situa-se na entrada da pelve, na região de cruzamento do ureter com vasos ilíacos."},{"id":35,"name":"Parte pélvica","group":"Ureter — porções e constrições","marker":"6","location":"Trecho que percorre a parede lateral da pelve em direção à bexiga; na mulher, passa inferiormente à artéria uterina.","bloom":"Avaliar","dialogue":["Após uma cirurgia ginecológica, há suspeita de lesão de um tubo perto do colo uterino.","A artéria uterina costuma passar acima dele: lembre “água sob a ponte”.","A lesão pode dificultar a passagem da urina para a bexiga."],"question":"Numa cirurgia junto ao colo do útero, alguém propõe ligar a artéria uterina sem verificar estruturas inferiores. Qual risco anatômico justifica atenção especial?","options":["O ureter pélvico passa inferiormente à artéria uterina e pode ser lesionado.","O tubo de maior risco junto ao colo uterino é a uretra, que cruza inferiormente a artéria uterina.","A artéria uterina normalmente passa abaixo do ureter, então o risco principal está em um ramo superior."],"challenge":"Elabore uma legenda didática para “água sob a ponte” sem confundir ureter com uretra.","correct":0,"explanation":"Na pelve feminina, o ureter cruza inferiormente à artéria uterina próximo ao colo uterino, relação importante durante procedimentos ginecológicos."},{"id":36,"name":"Parte intramural","group":"Ureter — porções e constrições","marker":"7","location":"Trecho terminal do ureter que atravessa obliquamente a parede da bexiga.","bloom":"Analisar","dialogue":["Uma criança apresenta retorno de urina da bexiga aos ureteres e infecções urinárias repetidas.","O trajeto oblíquo através da parede vesical ajuda normalmente a impedir esse retorno.","Se o mecanismo valvular falha, pode ocorrer refluxo vesicoureteral."],"question":"Uma criança apresenta refluxo de urina da bexiga para o ureter. Qual falha anatômica torna o retorno mais plausível?","options":["O detrusor garante ausência completa de refluxo, independentemente do trajeto intramural do ureter.","Um estreitamento na artéria renal é a causa anatômica direta do refluxo da bexiga para o ureter.","Um trajeto intramural ureteral cujo mecanismo antirrefluxo não funciona adequadamente."],"challenge":"Faça um diagrama comparando fluxo normal e refluxo em uma seta.","correct":2,"explanation":"O percurso oblíquo do ureter na parede vesical contribui para evitar o refluxo vesicoureteral."},{"id":37,"name":"Junção pieloureteral","group":"Ureter — porções e constrições","marker":"Constrição","location":"Ponto de transição da pelve renal, em funil, para o ureter proximal.","bloom":"Analisar","dialogue":["Um recém-nascido tem hidronefrose com dilatação da pelve renal e ureter não dilatado.","A investigação sugere estreitamento no início do ducto que sai do rim.","É um dos estreitamentos clássicos da via urinária superior."],"question":"Um recém-nascido tem pelve renal dilatada, mas o ureter abaixo dela não está dilatado. Qual hipótese localiza melhor o gargalo do fluxo?","options":["Obstrução na junção entre a pelve renal e o ureter proximal.","O gargalo está no ureter distal, mesmo com a parte proximal e todo o ureter sem dilatação.","A obstrução está no colo vesical, o que explicaria dilatação exclusiva da pelve renal."],"challenge":"Explique por que a ausência de dilatação do ureter é uma pista de localização.","correct":0,"explanation":"Uma obstrução na junção pieloureteral pode dilatar a pelve e os cálices sem necessariamente dilatar o ureter distal."},{"id":38,"name":"Cruzamento dos vasos ilíacos","group":"Ureter — porções e constrições","marker":"Constrição","location":"Ponto em que o ureter passa anteriormente à região dos vasos ilíacos na entrada da pelve.","bloom":"Aplicar/Analisar","dialogue":["Um cálculo permanece parado na linha da abertura superior da pelve.","Ele coincide com a passagem do ureter sobre os vasos ilíacos.","É uma região de estreitamento anatômico clássico, mas nem todos os cálculos param ali."],"question":"Na imagem, um cálculo se detém próximo à abertura superior da pelve, sobre o trajeto dos vasos ilíacos. Qual argumento localiza melhor o problema?","options":["O cálculo está na junção ureterovesical, situada precisamente na abertura superior da pelve.","O ponto corresponde ao cruzamento ureteral com vasos ilíacos, um estreitamento tradicionalmente descrito.","O estreitamento é a junção pieloureteral, que fica normalmente sobre os vasos ilíacos."],"challenge":"Compare em uma linha esse ponto com a junção pieloureteral.","correct":1,"explanation":"O cruzamento do ureter na entrada da pelve é um dos pontos clássicos de estreitamento, embora não seja local obrigatório de impactação."},{"id":39,"name":"Porção intramural","group":"Ureter — porções e constrições","marker":"Constrição","location":"Trecho estreito terminal que atravessa a parede da bexiga em direção ao óstio ureteral.","bloom":"Analisar","dialogue":["Uma tomografia mostra um cálculo bem próximo de entrar na bexiga, no estreitamento terminal do ureter.","O segmento está dentro da parede vesical, não no interior da uretra.","É uma das três regiões clássicas de estreitamento do ureter."],"question":"Um cálculo aparece quase entrando na bexiga, mas ainda está inserido no trajeto que cruza a parede vesical. Qual interpretação evita confundir os canais?","options":["O cálculo ainda está na parte abdominal, porque a parede da bexiga faz parte do retroperitônio superior.","Está na porção intramural do ureter, perto da junção ureterovesical.","O cálculo já está na uretra, pois a uretra é o canal que atravessa obliquamente a parede vesical."],"challenge":"Desenhe um limite claro entre ureter intramural e início da uretra.","correct":1,"explanation":"A porção intramural é o trecho terminal do ureter que atravessa a parede da bexiga, um local de estreitamento."},{"id":40,"name":"Ápice da bexiga","group":"Bexiga urinária","marker":"8","location":"Extremidade anterior e superior da bexiga, dirigida à sínfise púbica e conectada ao ligamento umbilical mediano.","bloom":"Analisar","dialogue":["Uma criança apresenta saída persistente de urina pelo umbigo por uma comunicação congênita.","A alteração envolve a persistência do úraco, ligado à extremidade anterior da bexiga.","No adulto normal, essa ligação forma o ligamento umbilical mediano."],"question":"Uma criança apresenta perda de urina pelo umbigo por persistência de uma comunicação embrionária. Que conexão anatômica ajuda a explicar o caminho inesperado?","options":["O trígono é a porção diretamente ligada ao umbigo pelo úraco.","O fundo vesical é o ponto de origem do ligamento umbilical mediano.","O ápice da bexiga conecta-se ao trajeto do úraco, remanescente no ligamento umbilical mediano."],"challenge":"Compare a função do úraco persistente e a do ligamento umbilical mediano normal.","correct":2,"explanation":"O ápice da bexiga é ligado ao trajeto do úraco; quando patente, pode haver comunicação entre bexiga e umbigo."},{"id":41,"name":"Corpo da bexiga","group":"Bexiga urinária","marker":"9","location":"Porção principal e distensível do reservatório, entre ápice, fundo e colo.","bloom":"Analisar","dialogue":["Uma pessoa sente urgência urinária porque a parede muscular do reservatório contrai involuntariamente.","O grande compartimento distensível muda de forma conforme se enche.","O músculo detrusor participa diretamente da expulsão da urina."],"question":"Na bexiga de uma pessoa com urgência urinária, o detrusor contrai antes do momento desejado. Qual raciocínio relaciona a estrutura ao sintoma?","options":["A urgência é explicada principalmente pelo peristaltismo ureteral, independentemente do detrusor.","A distensão do corpo vesical impede fisiologicamente qualquer contração involuntária.","Contrações involuntárias da parede do corpo vesical podem gerar vontade súbita de urinar."],"challenge":"Proponha uma explicação curta para a diferença entre enchimento e micção.","correct":2,"explanation":"O corpo é a porção principal distensível da bexiga e sua parede muscular participa do armazenamento e do esvaziamento."},{"id":42,"name":"Fundo da bexiga","group":"Bexiga urinária","marker":"10","location":"Base posteroinferior da bexiga; vizinha de estruturas reprodutivas e do reto no homem e da vagina na mulher.","bloom":"Aplicar/Analisar","dialogue":["Numa imagem pélvica, a equipe observa a parede posterior do reservatório próxima às vesículas seminais de um homem.","É uma região que recebe os ureteres nas áreas posterolaterais.","Não confunda fundo com ápice, que aponta anteriormente."],"question":"Uma lesão no reservatório urinário está junto às vesículas seminais. Em um corpo masculino, que face da bexiga a equipe provavelmente está analisando?","options":["O ápice, por ser a extremidade posterior da bexiga masculina.","O colo, porque é a principal superfície ampla de contato posterior com as vesículas seminais.","A base ou fundo vesical, voltada posteroinferiormente."],"challenge":"Compare a orientação do ápice e a orientação do fundo em um desenho sagital.","correct":2,"explanation":"O fundo da bexiga apresenta relações posteriores importantes, inclusive com as vesículas seminais no homem."},{"id":43,"name":"Colo da bexiga","group":"Bexiga urinária","marker":"11","location":"Região inferior, mais fixa, que afunila até o óstio interno e a uretra.","bloom":"Analisar","dialogue":["Um homem com próstata aumentada tem esvaziamento urinário difícil perto da saída do reservatório.","A região é a transição inferior da bexiga para a uretra.","O óstio interno da uretra está nesse ponto."],"question":"O paciente produz urina e a armazena, mas uma obstrução próxima à transição vesicouretral dificulta o esvaziamento. Qual região é o gargalo anatômico mais provável?","options":["O trígono, pois contém apenas as entradas dos ureteres, sem nenhuma abertura de saída.","O colo da bexiga, contínuo com o início da uretra.","O ápice da bexiga, pois ele constitui a via habitual para a uretra."],"challenge":"Marque a passagem entre armazenamento e eliminação no esquema vesical.","correct":1,"explanation":"O colo vesical afunila-se para o óstio interno e a uretra; alterações nessa região podem dificultar a saída da urina."},{"id":44,"name":"Trígono da bexiga","group":"Bexiga urinária","marker":"12","location":"Área triangular lisa no assoalho interno, delimitada pelos dois óstios ureterais e pelo óstio interno da uretra.","bloom":"Analisar","dialogue":["Na cistoscopia, a câmera encontra uma área lisa e triangular enquanto outras partes mostram pregas.","Dois orifícios de entrada da urina formam os ângulos superiores.","O início da uretra constitui o vértice inferior."],"question":"Na cistoscopia aparece um triângulo liso com duas entradas superiores e uma saída inferior. Se a equipe confundir um vértice com outro, o que pode interpretar erroneamente?","options":["A posição dos óstios ureterais e do óstio interno da uretra no trígono.","O orifício inferior seria uma terceira entrada ureteral, e não a abertura uretral.","As duas aberturas superiores seriam saídas para a uretra, enquanto a inferior receberia urina."],"challenge":"Crie um mapa triangular com setas de entrada e saída da urina.","correct":0,"explanation":"Os dois óstios ureterais delimitam os ângulos superiores do trígono; o óstio uretral interno forma o vértice inferior."},{"id":45,"name":"Prega interuretérica","group":"Bexiga urinária","marker":"13","location":"Crista mucosa transversal entre os dois óstios ureterais, delimitando a borda superior do trígono.","bloom":"Aplicar/Analisar","dialogue":["Em uma cistoscopia, a turma procura uma pequena crista que une os pontos de entrada dos ureteres.","Ela é uma importante referência para orientar-se no interior da bexiga.","Essa prega forma a base superior da região triangular lisa."],"question":"Um endoscopista encontra a crista que liga as duas entradas dos ureteres. Que uso espacial dessa crista faz mais sentido?","options":["A crista forma o vértice inferior do trígono e se prolonga diretamente pela uretra.","A crista delimita o ápice anterior da bexiga, e não o trígono.","Localizar o limite superior do trígono vesical e orientar os óstios ureterais."],"challenge":"Desenhe dois óstios ligados por uma prega e situe o vértice inferior do trígono.","correct":2,"explanation":"A prega interuretérica conecta os óstios ureterais e marca o limite superior da área trigonal."},{"id":46,"name":"Fossa retroureterica","group":"Bexiga urinária","marker":"14","location":"Pequena depressão da superfície interna da bexiga posterior à prega interuretérica.","bloom":"Avaliar","dialogue":["Na aula de cistoscopia, a professora pede para localizar uma depressão logo atrás da crista entre os óstios ureterais.","Não é uma nova abertura de drenagem, e sim um acidente anatômico de localização.","Seu nome já indica que está na região posterior ao marco interuretérico."],"question":"Em uma imagem endoscópica, aparece uma pequena depressão atrás da prega interuretérica. Um colega a chama de “terceiro ureter”. Qual resposta é mais adequada?","options":["Toda depressão posterior à prega é um terceiro óstio ureteral funcional.","Corrigir: pode ser a fossa retroureteral, uma depressão anatômica, não uma nova abertura.","A depressão corresponde ao óstio interno da uretra, normalmente localizado atrás da prega interuretérica."],"challenge":"Formule uma pista visual para diferenciar depressão mucosa de óstio ureteral.","correct":1,"explanation":"A fossa retroureteral é uma depressão posterior à prega interuretérica, não um óstio de drenagem."},{"id":47,"name":"Pregas vesicais","group":"Bexiga urinária","marker":"15","location":"Dobras da mucosa vesical mais evidentes quando a bexiga está vazia, exceto na região tipicamente lisa do trígono.","bloom":"Avaliar","dialogue":["Uma cistoscopia revela dobras mucosas que quase desaparecem após o enchimento normal da bexiga.","Isso pode ser um aspecto fisiológico, diferente de uma massa fixa.","O trígono é a área que habitualmente permanece lisa."],"question":"Um aluno vê rugas vesicais numa bexiga pouco cheia e conclui imediatamente que são massas. Qual observação ajudaria a evitar esse erro?","options":["Pregas mucosas podem diminuir com a distensão; o trígono permanece tipicamente liso.","O trígono costuma apresentar mais pregas que o restante da bexiga e as perde ao distender-se.","Pregas vesicais mantêm o mesmo aspecto independentemente do volume de enchimento."],"challenge":"Descreva como comparar uma mesma região em bexiga vazia e cheia.","correct":0,"explanation":"As pregas vesicais são dobras mucosas fisiológicas que se aplainam à medida que o corpo vesical distende, diferindo da região lisa do trígono."},{"id":48,"name":"Úvula vesical","group":"Bexiga urinária","marker":"16","location":"Pequena elevação mucosa na proximidade do óstio interno da uretra, frequentemente mais saliente no sexo masculino.","bloom":"Avaliar","dialogue":["Durante a cistoscopia de um homem, nota-se uma pequena saliência junto à abertura de saída vesical.","Pode tornar-se proeminente com alterações no lobo mediano da próstata.","Não é um dos óstios de entrada dos ureteres."],"question":"Perto da saída vesical de um homem surge uma elevação mucosa, próxima da uretra e eventualmente associada à próstata. Qual interpretação anatômica é mais apropriada antes de concluir que se trata de um óstio extra?","options":["A elevação pode corresponder à úvula vesical, cuja proeminência varia, especialmente junto a alterações prostáticas.","É provavelmente um óstio ureteral mediano localizado abaixo do trígono.","É provavelmente a prega interuretérica, que forma uma saliência única na saída da uretra."],"challenge":"Escreva uma frase que diferencie relevo anatômico, óstio e alteração patológica sem fazer diagnóstico apenas pela forma.","correct":0,"explanation":"A úvula vesical é uma elevação próxima ao óstio interno da uretra, mais evidente em alguns homens."},{"id":49,"name":"Óstio do ureter","group":"Bexiga urinária","marker":"17","location":"Orifício de entrada de cada ureter na bexiga, nos ângulos superolaterais do trígono.","bloom":"Avaliar","dialogue":["Durante a cistoscopia, a médica observa um jato de urina de um lado, mas não percebe jato do outro durante a observação.","Cada jato emerge da abertura terminal de um ureter; a ausência isolada não confirma obstrução.","A equipe investiga se há cálculo ou outro motivo de dificuldade de drenagem."],"question":"Durante a cistoscopia, há jato visível em um óstio ureteral e nenhum jato observado no outro por alguns instantes. Qual conclusão é cientificamente mais cuidadosa?","options":["A presença de um jato à direita comprova que o ureter esquerdo também está livre de obstrução.","A ausência momentânea do jato é suficiente para confirmar obstrução total daquele ureter.","Os jatos podem ser intermitentes; deve-se correlacionar a observação com outros achados."],"challenge":"Proponha uma segunda informação necessária antes de interpretar a assimetria.","correct":2,"explanation":"Os óstios ureterais recebem a urina na bexiga, mas não observar jato em um curto intervalo não confirma, isoladamente, uma obstrução."},{"id":50,"name":"Óstio interno da uretra","group":"Bexiga urinária","marker":"18","location":"Abertura na região inferior do trígono e colo vesical, que marca o início da uretra.","bloom":"Analisar","dialogue":["Na endoscopia, a turma identifica o único orifício inferior do trígono que conduz a urina para fora da bexiga.","Os outros dois orifícios superiores recebem urina dos ureteres.","Esse orifício inferior é contínuo com a uretra."],"question":"No trígono, uma abertura inferior conduz a urina para fora da bexiga, enquanto duas superiores a recebem. Qual inferência sobre o fluxo é correta?","options":["Todos os orifícios do trígono são entradas de urina na bexiga, inclusive o inferior.","A saída inferior marca o óstio interno da uretra, na transição para a micção.","A saída inferior retorna ao ureter, enquanto as duas superiores se dirigem à uretra."],"challenge":"Modele com setas duas entradas e uma saída da bexiga.","correct":1,"explanation":"O óstio interno da uretra corresponde ao vértice inferior do trígono e dá continuidade à uretra."},{"id":51,"name":"Uretra feminina","group":"Uretra feminina","marker":"—","location":"Canal curto, cerca de 3–4 cm, anterior à vagina; abre-se no vestíbulo vulvar, anteriormente ao óstio vaginal.","bloom":"Analisar","dialogue":["Uma universitária apresenta disúria e aumento da frequência urinária por infecção urinária baixa.","O canal feminino de saída da urina é curto e abre-se anteriormente ao óstio vaginal.","Seu comprimento é uma das características anatômicas que contribuem para a maior frequência de infecções ascendentes."],"question":"Por que a menor extensão do canal urinário feminino é uma pista anatômica relevante numa discussão sobre infecção urinária ascendente?","options":["O comprimento uretral, isoladamente, determina todas as infecções, independentemente de outros fatores.","A uretra mais curta impediria a chegada de microrganismos à bexiga por oferecer menor trajeto.","Porque uma uretra mais curta reduz a distância de acesso de microrganismos à bexiga, embora não explique todos os casos."],"challenge":"Crie uma comparação respeitosa e anatômica entre os trajetos uretrais feminino e masculino.","correct":2,"explanation":"A uretra feminina é curta e se abre no vestíbulo, característica anatômica relacionada ao risco de infecções ascendentes."},{"id":52,"name":"Porção intramural","group":"Uretra masculina","marker":"19","location":"Segmento inicial da uretra masculina atravessando o colo vesical, antes da parte prostática.","bloom":"Analisar","dialogue":["Após cirurgia do colo da bexiga, um paciente passa a apresentar ejaculação retrógrada.","O mecanismo de fechamento no colo vesical pode ser alterado pela cirurgia.","Estamos no segmento inicial da uretra masculina, antes de atravessar a próstata."],"question":"Após cirurgia do colo vesical, um homem ejacula parte do sêmen para a bexiga. Que alteração da arquitetura local pode explicar esse caminho invertido?","options":["A alteração dependeria exclusivamente do canal esponjoso, sem participação do mecanismo de fechamento vesical.","O quadro exige abertura dos ductos ejaculatórios diretamente na bexiga, apesar do colo íntegro.","Comprometimento do fechamento no colo, envolvendo a região uretral intramural."],"challenge":"Desenhe as direções habituais da urina e do sêmen e a direção alterada na ejaculação retrógrada.","correct":2,"explanation":"A região do colo vesical e da uretra intramural participa do mecanismo que dificulta a passagem retrógrada do sêmen para a bexiga."},{"id":53,"name":"Porção prostática","group":"Uretra masculina","marker":"20","location":"Segmento da uretra masculina que atravessa a próstata e recebe os ductos ejaculatórios e prostáticos.","bloom":"Analisar","dialogue":["Um homem com hiperplasia prostática benigna passa a urinar com jato fraco e dificuldade de iniciar a micção.","A glândula aumentada envolve uma parte do canal urinário masculino.","Os ductos ejaculatórios também se abrem nesse segmento."],"question":"Em um homem, a próstata aumenta de volume e o jato urinário enfraquece. O que torna essa relação anatômica particularmente direta?","options":["A uretra membranosa seria atravessada pela próstata, por isso sua compressão explicaria o jato fraco.","A uretra prostática atravessa a glândula e pode ser comprimida pelo aumento prostático.","A uretra esponjosa seria envolvida pela próstata, de modo que o aumento prostático a estreitaria diretamente."],"challenge":"Compare a relação entre uretra prostática e uretra esponjosa com os tecidos que as envolvem.","correct":1,"explanation":"A porção prostática da uretra passa pelo interior da próstata, onde também se abrem ductos do sistema reprodutor."},{"id":54,"name":"Porção membranosa","group":"Uretra masculina","marker":"21","location":"Trecho curto da uretra masculina situado inferiormente à próstata, atravessando a região do esfíncter externo.","bloom":"Avaliar","dialogue":["Após fratura grave da pelve, um homem apresenta sangramento no meato e suspeita de lesão uretral.","A equipe evita instrumentação cega e solicita avaliação apropriada.","O segmento curto abaixo da próstata está próximo ao esfíncter externo e pode ser lesionado em traumas pélvicos."],"question":"Após fratura pélvica com sangue no meato uretral, um colega sugere passar uma sonda sem avaliar a lesão. Qual resposta integra segurança e anatomia?","options":["Suspeitar de lesão uretral posterior, incluindo a região membranosa, e solicitar avaliação apropriada antes de instrumentação.","A porção membranosa não possui relação com lesões pélvicas, então a instrumentação cega seria apropriada.","Sangue no meato excluiria a uretra posterior; só o segmento esponjoso poderia ser atingido."],"challenge":"Justifique por que a posição da uretra membranosa explica sua vulnerabilidade em certos traumas.","correct":0,"explanation":"A uretra membranosa situa-se abaixo da próstata e próxima ao esfíncter externo; trauma pélvico com sangramento exige avaliação adequada antes de instrumentação às cegas."},{"id":55,"name":"Porção esponjosa","group":"Uretra masculina","marker":"22","location":"Segmento mais longo da uretra masculina, percorrendo o corpo esponjoso do pênis até o óstio uretral externo.","bloom":"Analisar","dialogue":["Um paciente com trauma peniano anterior apresenta estreitamento do canal que percorre o corpo esponjoso.","O sintoma principal é jato fraco após lesão local.","Esse segmento segue até a abertura uretral na glande."],"question":"Após trauma peniano, um homem tem jato fraco por estreitamento do canal que percorre o corpo esponjoso. Qual conclusão liga corretamente lesão e trajeto?","options":["A porção membranosa ocupa quase todo o corpo do pênis e segue até o meato externo.","A lesão envolve a uretra esponjosa, porção longa que segue até o óstio externo.","A porção prostática percorre o corpo esponjoso e seria a principal afetada após lesão peniana."],"challenge":"Crie um mapa longitudinal com as porções uretrais masculinas até o meato externo.","correct":1,"explanation":"A uretra esponjosa percorre o corpo esponjoso do pênis e pode desenvolver estenoses após lesão."}];
